<script setup>
import {computed,ref,watch} from 'vue'
import {resolutionExamples,resolutionPredicateSteps} from '../services/predicate-inference.mjs'
import SimulationControls from './SimulationControls.vue'
import PredicateCode from './PredicateCode.vue'
const preset=ref('kings'),clauses=ref(resolutionExamples.kings.clauses),step=ref(0),input=ref(clauses.value.join('\n')),error=ref('')
const trace=computed(()=>Array.from(resolutionPredicateSteps(clauses.value))),state=computed(()=>trace.value[Math.min(step.value,trace.value.length-1)]),key=computed(()=>JSON.stringify(clauses.value))
watch(key,()=>step.value=0);watch(preset,()=>{clauses.value=resolutionExamples[preset.value].clauses;input.value=clauses.value.join('\n');error.value=''})
function apply(){try{const c=input.value.split('\n').map(x=>x.trim()).filter(Boolean);Array.from(resolutionPredicateSteps(c));clauses.value=c;error.value=''}catch(e){error.value=e.message}}
const message=computed(()=>{const s=state.value;if(s.phase==='success')return 'Đã dẫn xuất clause rỗng □. Tập clause đầu vào không thỏa được. Nếu đã thêm phủ định truy vấn, đây là chứng minh phản chứng cho truy vấn.';if(s.phase==='budget')return 'Hết giới hạn tính toán. Chưa có clause rỗng không chứng minh tập clause thỏa được hoặc truy vấn sai.';if(s.phase==='finished')return 'Lượt tìm kiếm không sinh thêm clause. Đây là bộ xem giới hạn, không phải chứng nhận tổng quát về tính thỏa được của logic vị từ.';if(s.phase==='factor')return 'Hợp nhất hai literal cùng dấu trong một clause, giữ một literal và áp dụng phép thế cho toàn clause.';if(s.phase==='resolve')return 'Hai clause cha đã được đổi tên biến tách biệt. Khử một cặp literal đối dấu sau hợp nhất rồi áp dụng phép thế lên mọi literal còn lại.';return 'Mỗi clause được hiểu có lượng từ với mọi cho các biến của nó. Clause cuối trong ví dụ vua là phủ định truy vấn Evil(John).'})
</script>
<template><section class="math-lab predicate-resolution" aria-label="Mô phỏng hợp giải và factoring logic vị từ"><label>Trường hợp<select v-model="preset"><option v-for="(p,k) in resolutionExamples" :key="k" :value="k">{{ p.title }}</option></select></label><SimulationControls v-model="step" :max="trace.length-1" :reset-key="key"/><p class="predicate-status" role="status">{{ message }}</p><div v-if="state.parents" class="resolution-operation"><p>Cha: {{ state.parents.map(x=>'C'+x).join(' và ') }}.</p><p>Literal được xét: {{ state.pivot.join(' ; ') }}.</p><p v-for="([v,t]) in Object.entries(state.theta||{})" :key="v" class="term-row">{{ v }} ↦ {{ t }}</p></div><ol class="predicate-clauses"><li v-for="c in state.clauses" :key="c.id" :class="{empty:c.text==='□',derived:c.text===state.derived}"><strong>C{{ c.id }}</strong><span class="term-row">{{ c.text }}</span><small v-if="c.parents.length">{{ c.type==='factor'?'Factoring':'Hợp giải' }} từ {{ c.parents.map(x=>'C'+x).join(', ') }}</small><small v-else>Đầu vào</small></li></ol><details class="resolution-input"><summary>Tự nhập tập clause</summary><p>Mỗi dòng là một clause. Dùng | cho tuyển, ~ cho phủ định và ?x cho biến. [] biểu diễn clause rỗng. Các mệnh đề có lượng từ phải được chuẩn hóa và Skolem hóa đúng trước khi nhập. Bằng nhau không được hỗ trợ.</p><label>Clause đầu vào<textarea v-model="input" rows="7" spellcheck="false"/></label><button type="button" @click="apply">Dùng tập clause</button><p v-if="error" role="alert">{{ error }}</p></details><details><summary>Giả thiết và giới hạn bộ xem</summary><p>Chuẩn hóa biến trước mỗi phép hợp giải. Mỗi bước chỉ khử một cặp literal. Factoring áp dụng phép thế lên cả clause. Hai literal đối dấu chỉ hợp nhất được chưa làm một clause trở thành hằng đúng. Chỉ cặp đối dấu giống hệt nhau trong cùng clause mới được bỏ như một hằng đúng.</p><p>Bộ xem xử lý tối đa 12 clause đầu vào, 8 literal mỗi clause, 40 clause sinh ra và 400 lần thử pivot. Danh sách clause được lưu để xem lại chứng chỉ, vì vậy bộ nhớ quan sát khác bộ nhớ của một chiến lược tìm chứng minh tối ưu.</p></details><PredicateCode name="resolutionPredicateSteps" :phase="state.phase" :derived="!!state.clauses.at(-1)?.parents.length"/></section></template>
<style scoped>
.predicate-resolution{min-width:0}.predicate-resolution label{display:grid;gap:6px;font:var(--fs-small)/1.7 var(--font-ui)}.predicate-resolution :is(select,textarea,button){min-height:44px;min-width:0;max-width:100%;padding:8px;border:1px solid var(--control);border-radius:var(--radius);color:var(--ink);background:var(--paper);font:inherit}.predicate-resolution textarea{width:100%;font:13px/1.7 var(--font-code)}.predicate-status{padding:12px;border-left:3px solid var(--tim);background:var(--tim-soft)}.resolution-operation{padding:12px;border:1px solid var(--rule);background:var(--paper);border-radius:var(--radius);overflow-wrap:anywhere}.predicate-clauses{display:grid;gap:10px;padding:0;list-style:none}.predicate-clauses li{display:grid;grid-template-columns:4ch minmax(0,1fr);gap:8px;align-items:start;padding:12px;background:var(--paper);border:1px solid var(--rule);border-radius:var(--radius)}.predicate-clauses li.derived{border-left:3px solid var(--tim)}.predicate-clauses li.empty{border-color:var(--xanh);background:var(--xanh-soft)}.predicate-clauses strong{white-space:nowrap;font:600 14px/1.8 var(--font-code)}.predicate-clauses small{grid-column:2;color:var(--ink-2);font:var(--fs-small)/1.6 var(--font-ui)}.term-row{font:14px/1.8 var(--font-code);overflow-wrap:anywhere}summary{min-height:44px;cursor:pointer}:is(select,textarea,button,summary):focus-visible{outline:3px solid var(--tim);outline-offset:3px}
</style>
